term_id = #{termId}, class_code = #{classCode}, class_name = #{className}, dept_id = #{deptId}, major_id = #{majorId}, grade_year = #{gradeYear}, head_teacher = #{headTeacher}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
